-- Winterspring: creature abilities
-- Most of the zone's creatures (the Winterfall furbolgs, the Frostmaul giants, the Frostsaber cats, the chimaeras, owlbeasts and yetis) had no AI or ran classic rows. Port their abilities from the
-- Cataclysm data, and from the classic data where Cataclysm has none, keeping the quest scripts already in place; gossip and quest
-- reward scripts of the references are left out. The creatures no reference scripts cast their sniffed spells (creature_template
-- spell1-8).

SET @ENTRIES := '7428,7429,7430,7431,7432,7433,7434,7438,7439,7440,7441,7442,7448,7450,7451,7452,7453,7454,7455,7456,7458,7459,7460,7523,7524,10196,10197,10198,10199,10200,10661,10738,10741,10806,10807,10916,48664,48665,48678,48740,48765,48767,48768,48952,48960,49178,49217,49235,49346,49347,49565,50044,50250,50251,50312,50313,50315,50316,50317,50319,50320,50321,50322';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '14881,48670,48918,50258,50325';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
